{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/store-locations.json
    The stores of a shop: name, a badge of its kind (pickup or store only), address, hours, phone, a note and the services. Axes: layout (cards, list: one row per store, map: compact cards beside a map picture), tone.
    Props (p): id, title, lead, stores, empty, kinds, labels, layout, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_stores = ($p['stores'] ?? null)}
{var $v_empty = ($p['empty'] ?? '')}
{var $v_kinds = ($p['kinds'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'cards')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_18}
  {if og_t(og_eq(og_len($v_stores), 0))}
    {=og_include('blocks/empty-state.latte', ['p' => ['icon' => 'store', 'title' => $v_empty]])|noescape}
  {else}
    {capture $c_17}
      {capture $c_15}
        {foreach og_l($v_stores) as $v_s}
          {capture $c_14}
            {capture $c_3}
              {capture $c_1}
                {=og_text(og_at($v_kinds, og_get($v_s, ['kind'])))}
              {/capture}
              {=og_include('compose/Badge.latte', ['variant' => 'outline', 'size' => 'default', 'class' => 'w-fit', 'children' => (string) $c_1])|noescape}
              {capture $c_2}
                {=og_text(og_get($v_s, ['name']))}
              {/capture}
              {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'lg', 'weight' => 'bold', 'children' => (string) $c_2])|noescape}
            {/capture}
            {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_3])|noescape}
            {capture $c_10}
              {capture $c_5}
                {=og_include('icons/LucideIcon.latte', ['name' => 'map-pin', 'size' => 16])|noescape}
                {capture $c_4}
                  {=og_text(og_get($v_s, ['address']))}
                {/capture}
                {=og_include('compose/Inline.latte', ['children' => (string) $c_4])|noescape}
              {/capture}
              {=og_include('compose/ListItem.latte', ['class' => 'flex items-center gap-2', 'children' => (string) $c_5])|noescape}
              {capture $c_7}
                {=og_include('icons/LucideIcon.latte', ['name' => 'clock', 'size' => 16])|noescape}
                {capture $c_6}
                  {=og_text(og_get($v_s, ['hours']))}
                {/capture}
                {=og_include('compose/Inline.latte', ['children' => (string) $c_6])|noescape}
              {/capture}
              {=og_include('compose/ListItem.latte', ['class' => 'flex items-center gap-2', 'children' => (string) $c_7])|noescape}
              {capture $c_9}
                {=og_include('icons/LucideIcon.latte', ['name' => 'phone', 'size' => 16])|noescape}
                {capture $c_8}
                  {=og_text(og_nbsp(og_get($v_s, ['phone'])))}
                {/capture}
                {=og_include('compose/Link.latte', ['href' => og_url(og_s(og_tpl('tel:{0}', [og_get($v_s, ['phone'])]))), 'variant' => 'default', 'children' => (string) $c_8])|noescape}
              {/capture}
              {=og_include('compose/ListItem.latte', ['class' => 'flex items-center gap-2', 'children' => (string) $c_9])|noescape}
            {/capture}
            {=og_include('compose/List.latte', ['tag' => 'ul', 'class' => og_s((og_t(og_eq($v_layout, 'list')) ? 'flex flex-wrap gap-x-8 gap-y-2 text-sm' : 'flex flex-col gap-2 text-sm')), 'children' => (string) $c_10])|noescape}
            {if og_t(og_eq($v_layout, 'cards'))}
              {capture $c_11}
                {=og_text(og_get($v_s, ['note']))}
              {/capture}
              {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_11])|noescape}
              {capture $c_13}
                {foreach og_l(og_get($v_s, ['services'])) as $v_v}
                  {capture $c_12}
                    {=og_text($v_v)}
                  {/capture}
                  {=og_include('compose/Badge.latte', ['variant' => 'secondary', 'size' => 'default', 'children' => (string) $c_12])|noescape}
                {/foreach}
              {/capture}
              {=og_include('compose/Group.latte', ['gap' => '2', 'class' => 'flex-wrap', 'children' => (string) $c_13])|noescape}
            {/if}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '4', 'class' => og_s((og_t(og_eq($v_layout, 'list')) ? 'border-b border-border pb-4' : 'rounded bg-card inset-ring inset-ring-border p-6')), 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_14])|noescape}
        {/foreach}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'cards')) ? 'grid grid-cols-1 gap-4 md:grid-cols-2' : 'flex flex-col gap-4')), 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_15])|noescape}
      {if og_t(og_eq($v_layout, 'map'))}
        {capture $c_16}
          {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_labels, ['map']), 'ratio' => '1/1']])|noescape}
        {/capture}
        {=og_include('compose/Box.latte', ['class' => 'md:sticky md:top-8', 'children' => (string) $c_16])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => og_s(og_cnv(['grid grid-cols-1 gap-8', (og_t(og_eq($v_layout, 'map')) ? 'items-start md:grid-cols-2' : '')])), 'children' => (string) $c_17])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_18)])|noescape}
